package com.nextgen.gameaggregator.vendor.aviatrix.api.promowin;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import lombok.Data;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Aviatrix {@code /transactions/promoWin} request.
 *
 * <p>No longer a {@code BetResultData}: the payout runs through {@code /v1/promo/payout} rather than the
 * bet-result flow, so the bet-shaped accessors this DTO used to carry — round id, bet amount, win/loss,
 * turnover, settle times, {@code SETTLED} status — described a bet that never existed.
 */
@Data
@JsonIgnoreProperties(ignoreUnknown = true)
public class PromoWinDto {
    @NotBlank
    @Size(max = 255)
    private String cid; //channel id generated by vendor for identification

    @NotBlank
    @Size(max = 255)
    private String sessionToken;

    @NotBlank
    @Size(max = 50)
    private String playerId; //vendor player id

    @NotBlank
    @Size(max = 255)
    private String productId; // game id

    @NotBlank
    @Size(max = 255)
    private String txId; // transaction id, unique for every transaction

    @NotNull
    @Digits(integer = 20, fraction = 0)
    private BigDecimal amount;

    @NotBlank
    @Size(max = 5)
    private String currency; //currency used

    @NotNull
    @Valid
    private PromoDto promo;

    /** {@link #amount} in major units. Aviatrix quotes all money in minor units. */
    public BigDecimal getPayoutAmount() {
        return this.amount.divide(BigDecimal.valueOf(100), 2, RoundingMode.DOWN);
    }
}
